chrome.action.onClicked.addListener(e=>{e.windowId&&chrome.sidePanel.open({windowId:e.windowId})});chrome.runtime.onMessage.addListener((e,i,d)=>{e.type==="INSERT_EMOJI"&&chrome.tabs.query({active:!0,currentWindow:!0},n=>{n[0]&&n[0].id&&chrome.tabs.sendMessage(n[0].id,{type:"INSERT_EMOJI",emoji:e.emoji}).catch(o=>{console.log("Content script not available on this tab:",o.message)})})});
